/* eslint-disable space-in-parens */

import zeros = require( '@stdlib/ndarray/zeros' );
import snanvariance = require( './index' );


// TESTS //

// The function returns a number...
{
	const x = zeros( [ 10 ], {
		'dtype': 'float32'
	});

	snanvariance( [ x ], 1 ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not an array of ndarrays...
{
	snanvariance( '10', 1 ); // $ExpectError
	snanvariance( 10, 1 ); // $ExpectError
	snanvariance( true, 1 ); // $ExpectError
	snanvariance( false, 1 ); // $ExpectError
	snanvariance( null, 1 ); // $ExpectError
	snanvariance( undefined, 1 ); // $ExpectError
	snanvariance( [], 1 ); // $ExpectError
	snanvariance( {}, 1 ); // $ExpectError
	snanvariance( ( x: number ): number => x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided an invalid correction argument...
{
	const x = zeros( [ 10 ], {
		'dtype': 'float32'
	});

	snanvariance( [ x ] ); // $ExpectError
	snanvariance( [ x ], '1' ); // $ExpectError
	snanvariance( [ x ], {} ); // $ExpectError
	snanvariance( [ x ], null ); // $ExpectError
	snanvariance( [ x ], undefined ); // $ExpectError
}
